/**
 * Protocol API
 * 通訊協定管理相關 API
 */

(function() {
    const API = window.DMSAPI;
    if (!API) {
        console.error('DMSAPI not initialized. Please include api/index.js first.');
        return;
    }

    window.ProtocolAPI = {
        /**
         * 取得通訊協定清單
         * @param {Object} params - { type, keyword, pageNum, limit }
         * @returns {Promise}
         */
        getProtocolList: async function(params) {
            return API.get('/schideron/openApi/protocol/list', {
                ...params,
                requester: API.requester
            });
        },

        /**
         * 添加通訊協定
         * @param {Object} data - { name, type, gatewayId, gatewayIp }
         * @returns {Promise}
         */
        addProtocol: async function(data) {
            return API.post('/schideron/openApi/protocol/add', {
                ...data,
                requester: API.requester
            });
        },

        /**
         * 更新通訊協定
         * @param {string} id - 協定 ID
         * @param {Object} data - { name, type, gatewayId, gatewayIp, ... }
         * @returns {Promise}
         */
        updateProtocol: async function(id, data) {
            return API.put(`/schideron/openApi/protocol/edit/${id}`, {
                ...data,
                requester: API.requester
            });
        },

        /**
         * 刪除通訊協定
         * @param {string} id - 協定 ID
         * @returns {Promise}
         */
        deleteProtocol: async function(id) {
            return API.delete(`/schideron/openApi/protocol/delete/${id}`, {
                requester: API.requester
            });
        },

        /**
         * 取得子設備清單
         * @param {Object} params - { protocolId }
         * @returns {Promise}
         */
        getDeviceList: async function(params) {
            return API.get('/schideron/openApi/protocol/device/list', {
                protocolId: params?.protocolId || '8751cd88-7d70-11f0-a291-5254008c2c02',
                requester: API.requester
            });
        }
    };

    console.log('Protocol API initialized');
})();
